        return dgr_fail(p,SH_DEFAULT_READ_BOUNDS,at);
    if(p->receipt->work==SIZE_MAX || (p->input->work_limit && p->receipt->work>=p->input->work_limit))
        return dgr_fail(p,SH_DEFAULT_READ_BUDGET,at+offset);
    if(!p->input->read(p->input->read_context,at+offset,out,size))
        return dgr_fail(p,SH_DEFAULT_READ_MEMORY,at+offset);
