        return dgr_fail(p,SH_DEFAULT_READ_IMAGE,p->input->image_base);
    if(!dgr_image_read(p,pin->rva+pin->skip,bytes,pin->length-pin->skip))return 0;
    return !memcmp(bytes,pin->bytes+pin->skip,pin->length-pin->skip) ||
        dgr_fail(p,SH_DEFAULT_READ_PIN,dgr_address(p,which));
