    if((hash!=sentinel && !dgr_owner(p,hash)) || (indices!=sentinel && !dgr_owner(p,indices)))return 0;
    size_t reached=(list.flags==0 && list.count==list.capacity)?(size_t)list.capacity:(size_t)list.count;
    if(list.count<list.capacity)reached++; /* Actual miss assigns the next constructed record. */
